new:
        assert_eq!(choices[0].label, "Idle");
        assert_eq!(clip_display_name(slot.as_str(), &choices), "Idle");
    }

    #[test]
    fn animation_set_choice_cache_reuses_parse_until_file_stamp_changes() {
        let unique = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("test clock must be after Unix epoch")
            .as_nanos();
        let root = std::env::temp_dir().join(format!(
            "gameengine-adr0136-animation-set-cache-{}-{unique}",
            std::process::id()
        ));
        std::fs::create_dir_all(&root).expect("cache test directory must be created");

        let animation_set_id = AssetId::generate();
        let slot = engine_authoring::MotionSlotId::generate();
        let mut set = engine_authoring::AnimationSet::new(AssetId::generate());
        set.bindings.insert(
            slot.clone(),
            engine_authoring::AnimationBinding {
                name: "Idle".to_owned(),
                clip: engine_authoring::MotionSourceRef::native(AssetId::generate()),
                overlays: Vec::new(),
                events: Vec::new(),
            },
        );
        let set_path = root.join("hero.animset.json");
        std::fs::write(
            &set_path,
            set.to_canonical_json().expect("animation set must serialize"),
        )
        .expect("animation set fixture must be written");

        let mut manifest = engine::AssetManifest::default();
        manifest.insert(
            animation_set_id.clone(),
            engine::ManifestEntry {
                path: "hero.animset.json".to_owned(),
                name: Some("Hero".to_owned()),
                import_settings: engine::ImportSettings::default(),
            },
        );

        let entity = EntityId::generate();
        let mut scene = AuthoringScene::new();
        let mut transaction = Transaction::begin(&scene);
        transaction.apply(AuthoringCommand::CreateEntity {
            id: entity.clone(),
            name: "Hero".into(),
            parent: None,
        });
        transaction.apply(AuthoringCommand::AddComponent {
            entity: entity.clone(),
            component_type: animation_controller_type(),
            value: Value::Object(std::collections::BTreeMap::from([(
                "animation_set".to_owned(),
                Value::AssetRef(animation_set_id),
            )])),
        });
        transaction
            .commit(&mut scene)
            .expect("preview scene fixture must commit");

        let mut cache = None;
        let first =
            animation_clip_choices_cached(&mut cache, &scene, &entity, &manifest, Some(&root));
        let second =
            animation_clip_choices_cached(&mut cache, &scene, &entity, &manifest, Some(&root));
        assert!(Arc::ptr_eq(&first, &second));
        assert_eq!(first.len(), 1);

        set.bindings.insert(
            engine_authoring::MotionSlotId::generate(),
            engine_authoring::AnimationBinding {
                name: "Run".to_owned(),
                clip: engine_authoring::MotionSourceRef::native(AssetId::generate()),
                overlays: Vec::new(),
                events: Vec::new(),
            },
        );
        std::fs::write(
            &set_path,
            set.to_canonical_json().expect("updated animation set must serialize"),
        )
        .expect("updated animation set fixture must be written");
        let updated =
            animation_clip_choices_cached(&mut cache, &scene, &entity, &manifest, Some(&root));
        assert!(!Arc::ptr_eq(&first, &updated));
        assert_eq!(updated.len(), 2);

        let _ = std::fs::remove_dir_all(root);
    }
